sp_widget.client_script:
api.controller = function () {
    var c = this;
    c.year = new Date().getFullYear();
};

sp_widget.css:
.dpp-verify-wrapper {
  display: flex;
  justify-content: center;
  align-items: flex-start;
  padding: 32px 16px 64px;
  min-height: 80vh;
  background: linear-gradient(160deg, #f0f4f8 0%, #e8eef3 50%, #dce5ed 100%);
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
  -webkit-font-smoothing: antialiased;
}

/* ── Card ─────────────────────────────────────────── */
.dpp-card {
  width: 100%;
  max-width: 440px;
  background: #ffffff;
  border-radius: 20px;
  box-shadow: 0 8px 40px rgba(15, 23, 42, 0.08), 0 2px 8px rgba(15, 23, 42, 0.04);
  overflow: hidden;
  animation: cardEntrance 0.5s cubic-bezier(0.22, 1, 0.36, 1);
}
@keyframes cardEntrance {
  from { opacity: 0; transform: translateY(16px) scale(0.98); }
  to   { opacity: 1; transform: translateY(0) scale(1); }
}

.dpp-card-warning {
  box-shadow: 0 8px 40px rgba(185, 28, 28, 0.1), 0 2px 8px rgba(185, 28, 28, 0.06);
}

/* ── Header ───────────────────────────────────────── */
.dpp-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 18px 24px;
  background: linear-gradient(135deg, #0f172a 0%, #1e293b 100%);
}

.dpp-logo {
  display: flex;
  align-items: center;
  gap: 10px;
}
.dpp-logo-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  border-radius: 8px;
  background: linear-gradient(135deg, #10b981 0%, #059669 100%);
  color: #fff;
  font-size: 14px;
  font-weight: 700;
}
.dpp-logo-text {
  color: #ffffff;
  font-size: 17px;
  font-weight: 700;
  letter-spacing: 0.3px;
}
.dpp-header-tag {
  font-size: 10px;
  letter-spacing: 2px;
  color: rgba(255,255,255,0.45);
  font-weight: 600;
}

/* ── Warning banner ───────────────────────────────── */
.dpp-warning-banner {
  display: flex;
  gap: 12px;
  padding: 14px 24px;
  background: #fef2f2;
  border-bottom: 1px solid #fecaca;
}
.dpp-warning-banner > .fa {
  color: #dc2626;
  font-size: 18px;
  margin-top: 2px;
  flex-shrink: 0;
}
.dpp-warning-content strong {
  display: block;
  color: #991b1b;
  font-size: 13px;
  margin-bottom: 2px;
}
.dpp-warning-content p {
  color: #b91c1c;
  font-size: 12px;
  line-height: 1.5;
  margin: 0;
}

/* ── Product hero ─────────────────────────────────── */
.dpp-product-hero {
  display: flex;
  align-items: flex-start;
  gap: 16px;
  padding: 24px 24px 20px;
}
.dpp-product-icon-wrap {
  flex-shrink: 0;
  width: 52px;
  height: 52px;
  border-radius: 14px;
  background: linear-gradient(135deg, #eff6ff 0%, #dbeafe 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  color: #3b82f6;
}
.dpp-product-info {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
}
.dpp-product-name {
  font-size: 20px;
  font-weight: 700;
  color: #0f172a;
  margin: 0;
  line-height: 1.3;
  word-wrap: break-word;
}
.dpp-product-model {
  font-size: 14px;
  color: #64748b;
  font-weight: 500;
}
.dpp-product-mfg {
  font-size: 12px;
  color: #94a3b8;
  margin-top: 2px;
}
.dpp-product-mfg .fa { margin-right: 4px; font-size: 11px; }

/* ── Status grid ──────────────────────────────────── */
.dpp-status-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
  padding: 0 24px 20px;
}
.dpp-status-card {
  background: #f8fafc;
  border-radius: 12px;
  padding: 14px 16px;
  border: 1px solid #f1f5f9;
}
.dpp-status-label {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 1px;
  color: #94a3b8;
  margin-bottom: 8px;
}

/* ── Badges ───────────────────────────────────────── */
.dpp-status-badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 5px 12px;
  border-radius: 20px;
  font-size: 12px;
  font-weight: 600;
}
.dpp-badge-good {
  background: #ecfdf5;
  color: #065f46;
  border: 1px solid #a7f3d0;
}
.dpp-badge-neutral {
  background: #fffbeb;
  color: #92400e;
  border: 1px solid #fde68a;
}
.dpp-badge-danger {
  background: #fef2f2;
  color: #991b1b;
  border: 1px solid #fecaca;
}

/* ── Service History (Layer 2 — authenticated) ────── */
.dpp-service-history {
  margin: 0 24px;
  padding: 16px 0;
  border-top: 1px solid #f1f5f9;
}
.dpp-service-history-header {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 1px;
  color: #94a3b8;
  text-transform: uppercase;
  margin-bottom: 12px;
}
.dpp-service-history-header .fa {
  font-size: 12px;
  color: #3b82f6;
}
.dpp-service-history-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
}
.dpp-service-stat {
  background: #f0f9ff;
  border-radius: 10px;
  padding: 12px 14px;
  border: 1px solid #e0f2fe;
  text-align: center;
}
.dpp-service-stat-value {
  font-size: 18px;
  font-weight: 700;
  color: #0369a1;
  line-height: 1.3;
}
.dpp-service-stat-label {
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.5px;
  color: #64748b;
  margin-top: 4px;
}

/* ── Passport ID bar ──────────────────────────────── */
.dpp-id-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin: 0 24px;
  padding: 12px 0;
  border-top: 1px solid #f1f5f9;
}
.dpp-id-label {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 1px;
  color: #94a3b8;
}
.dpp-id-value {
  font-size: 14px;
  font-weight: 700;
  color: #0f172a;
  font-family: 'SF Mono', 'Fira Code', Consolas, monospace;
  letter-spacing: 1px;
  background: #f8fafc;
  padding: 4px 10px;
  border-radius: 6px;
}

/* ── Footer ───────────────────────────────────────── */
.dpp-footer {
  padding: 16px 24px;
  background: #f8fafc;
  border-top: 1px solid #f1f5f9;
  text-align: center;
}
.dpp-footer-verified {
  font-size: 12px;
  color: #64748b;
  margin-bottom: 4px;
}
.dpp-footer-verified .fa { margin-right: 4px; }
.dpp-footer-brand {
  font-size: 11px;
  color: #cbd5e1;
}
.dpp-footer-disclaimer {
  font-size: 9px;
  color: #94a3b8;
  line-height: 1.4;
  margin-top: 8px;
  padding-top: 8px;
  border-top: 1px solid #e2e8f0;
}

/* ── Empty state ──────────────────────────────────── */
.dpp-card-empty .dpp-body { padding: 48px 24px 32px; }
.dpp-empty-icon-wrap {
  width: 64px;
  height: 64px;
  border-radius: 50%;
  background: #f1f5f9;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 20px;
  color: #94a3b8;
  font-size: 24px;
}
.dpp-empty-title {
  font-size: 18px;
  font-weight: 700;
  color: #334155;
  margin: 0 0 8px;
}
.dpp-empty-desc {
  font-size: 13px;
  color: #94a3b8;
  line-height: 1.6;
  margin: 0;
}

/* ── Responsive ───────────────────────────────────── */
@media (max-width: 480px) {
  .dpp-verify-wrapper { padding: 16px 12px 48px; }
  .dpp-card { border-radius: 16px; }
  .dpp-header { padding: 14px 20px; }
  .dpp-product-hero { padding: 20px 20px 16px; }
  .dpp-status-grid { padding: 0 20px 16px; gap: 8px; }
  .dpp-status-card { padding: 12px; }
  .dpp-product-name { font-size: 18px; }
  .dpp-id-bar { margin: 0 20px; }
  .dpp-header-tag { display: none; }
}

sp_widget.script:
(function () {
    data.found = false;
    data.product = '';
    data.model = '';
    data.manufacturer = '';
    data.passportStatus = '';
    data.passportStatusLabel = '';
    data.hasFraud = false;
    data.isWarning = false;
    data.warningMessage = '';
    data.assetId = '';
    data.scanDate = new GlideDateTime().getDisplayValue();

    // ── Layer 2: Authentication check ────────────────────────────
    data.isAuthenticated = gs.getSession().isLoggedIn();
    data.serviceCount = 0;
    data.lastServiceDate = '';

    var sysId = $sp.getParameter('sys_id');
    if (!sysId) { return; }

    // ── Delegate to the shared verification service ──────────────
    var svc = new DPPVerificationService();
    var result = svc.verify(sysId);

    if (!result.success) { return; }

    var body = result.body;
    data.found = true;
    data.product = body.product;
    data.model = body.model;
    data.manufacturer = body.manufacturer;
    data.passportStatus = body.passport_status;
    data.passportStatusLabel = body.passport_status_label;
    data.hasFraud = body.has_confirmed_fraud;
    data.assetId = body.passport_id;

    // ── Status severity mapping (UI-only concern) ────────────────
    var STATUS_MAP = {
        'active':             { severity: 'good' },
        'inspection_passed':  { severity: 'good' },
        'pending_inspection': { severity: 'neutral' },
        'suspended':          { severity: 'danger' },
        'flagged':            { severity: 'danger' },
        'decommissioned':     { severity: 'neutral' }
    };

    var mapped = STATUS_MAP[body.passport_status] || { severity: 'neutral' };
    data.statusSeverity = mapped.severity;

    // ── Warning banner for flagged / suspended passports ─────────
    var status = body.passport_status;
    if (status === 'flagged' || status === 'suspended') {
        data.isWarning = true;
        data.warningMessage = status === 'flagged'
            ? 'This device has been flagged due to a reported issue. Exercise caution before purchasing.'
            : 'This device passport has been suspended. Verification cannot be completed at this time.';
    }

    // ── Layer 2: Authenticated service history (non-PII) ─────────
    if (data.isAuthenticated) {
        var slGa = new GlideAggregate('x_1919710_refurt_0_service_log');
        slGa.addQuery('asset_passport', sysId);
        slGa.addAggregate('COUNT');
        slGa.query();
        if (slGa.next()) {
            data.serviceCount = parseInt(slGa.getAggregate('COUNT'), 10) || 0;
        }

        var latestGr = new GlideRecord('x_1919710_refurt_0_service_log');
        latestGr.addQuery('asset_passport', sysId);
        latestGr.orderByDesc('service_date');
        latestGr.setLimit(1);
        latestGr.query();
        if (latestGr.next()) {
            data.lastServiceDate = latestGr.getDisplayValue('service_date');
        }
    }
})();
